import numpy as np
import mujoco
from scipy.spatial.transform import Rotation
from PIL import Image

class Controller:
    def __init__(self,s):
        self.s=s
        self.m=s.model
        self.d=s.data
        self.ikd=mujoco.MjData(self.m)
        self.jids=[self.m.joint(f'robot0_joint{i}').id for i in range(1,8)]
        self.qids=np.array([self.m.jnt_qposadr[j] for j in self.jids])
        self.vids=np.array([self.m.jnt_dofadr[j] for j in self.jids])
        self.limits=self.m.jnt_range[self.jids]
        self.site=self.m.site('gripper0_right_grip_site').id
        self.R=Rotation.from_euler('z',.118).as_matrix()@np.diag([-1.,1.,-1.])
    def pos(self):return self.d.site_xpos[self.site].copy()
    def obj(self,name):return self.d.xpos[self.m.body(name+'_main').id].copy()
    def ik(self,pos,R=None,q=None):
        if R is None:R=self.R
        d=self.ikd
        d.qpos[:]=self.d.qpos
        if q is not None:d.qpos[self.qids]=q
        jp=np.zeros((3,self.m.nv));jr=jp.copy()
        for i in range(100):
            mujoco.mj_kinematics(self.m,d);mujoco.mj_comPos(self.m,d)
            ep=np.asarray(pos)-d.site_xpos[self.site]
            er=Rotation.from_matrix(R@d.site_xmat[self.site].reshape(3,3).T).as_rotvec()
            err=np.r_[ep,er*.4]
            if np.linalg.norm(err)<1e-5:break
            mujoco.mj_jacSite(self.m,d,jp,jr,self.site)
            J=np.vstack([jp[:,self.vids],.4*jr[:,self.vids]])
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,err)
            dq*=min(1,.15/max(np.max(np.abs(dq)),1e-9))
            d.qpos[self.qids]=np.clip(d.qpos[self.qids]+dq,self.limits[:,0]+.01,self.limits[:,1]-.01)
        return d.qpos[self.qids].copy(),np.linalg.norm(ep),np.linalg.norm(er)
    def step(self,q=None,grip=-1,base=None,torso=0):
        a=np.zeros(13);a[:7]=self.d.qpos[self.qids] if q is None else q;a[7]=grip;a[11]=torso;a[12]=-1
        if base is not None:a[8:11]=base;a[12]=1
        return self.s.step(a)
    def move(self,p,n=60,grip=-1,R=None,settle=10):
        p0=self.pos();R0=self.d.site_xmat[self.site].reshape(3,3).copy()
        Rt=self.R if R is None else R
        dr=Rotation.from_matrix(Rt@R0.T).as_rotvec()
        q=self.d.qpos[self.qids].copy()
        for i in range(n):
            t=(i+1)/n;t=t*t*(3-2*t)
            Ri=Rotation.from_rotvec(t*dr).as_matrix()@R0
            q,e,re=self.ik(p0+t*(np.asarray(p)-p0),Ri,q)
            self.step(q,grip)
        for i in range(settle):self.step(q,grip)
        print('MOVE',len(self.s.actions),'target',np.round(p,4),'eef',np.round(self.pos(),4),'ik',e,re,'sponge',np.round(self.obj('sponge'),4),'count',self.s.env.success_contact_time,flush=True)
    def hold(self,n=20,grip=1):
        q=self.s.targets[:7].copy()
        for _ in range(n):self.step(q,grip)
    def base(self,vel,n):
        q=self.d.qpos[self.qids].copy()
        for _ in range(n):self.step(q,-1,vel)
        for _ in range(10):self.step(q,-1,[0,0,0])
        print('BASE', self.d.xpos[self.m.body('robot0_link0').id],flush=True)
    def pic(self,name):Image.fromarray(self.s.render_grid()).save('/app/output/'+name+'.png')
    def report(self):
        print('STATE',self.s.check(),'count',self.s.env.success_contact_time,'eef',self.pos(),'sponge',self.obj('sponge'),'bowl',self.obj('bowl'),flush=True)
